import{z as s,x as A,o as e,c as d,q as o,j as r,D as a,d as t,s as B,S as i,b as l}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"长文档嵌入","description":"","frontmatter":{"title":"长文档嵌入","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/long-doc-embedding.md","filePath":"llm/long-doc-embedding.md","lastUpdated":1791413859000}'),p={name:"llm/long-doc-embedding.md"};function m(D,E,h,c,_,f){const n=A("Mermaid");return e(),d("div",null,[E[2]||(E[2]=o('<h1 id="长文档嵌入" tabindex="-1">长文档嵌入 <a class="header-anchor" href="#长文档嵌入" aria-label="Permalink to &quot;长文档嵌入&quot;">​</a></h1><div class="epigraph"><p>均值池化在两千 token 上把互相无关的小节平均成一个主题分类向量。检索对象必须先定义成「编码器能稳定表示」的长度。</p><footer>—— 对照切分课的块设计；层次化与晚切分是对超长输入的补丁</footer></div><p><a href="/llm/mteb">上一课</a>多数任务偏短句与短段。手册、论文、财报超出嵌入模型的训练长度后，单向量开始塌成主题。主干<a href="/llm/rag-chunking">切分</a>已从工程上切块；本课写表示侧：层次编码、滑动窗口、晚切分。缺口是长输入下的几何，不是再讲倒排。后课多模态嵌入换模态，长度问题同构。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>编码器有最大输入。超长则截断，信息在尾部丢失；或硬切后对块向量再平均，等于二层池化，细粒度更差。<span class="marginnote">术语翻译：「池化」就是把一串 token 向量压成一个向量，最常用的是取平均。可以想成把一整部电影压成一张海报：主题还在，情节没了。均值池化在长文档上尤其狠——第 3 节的细节被第 7 节平均掉，查询那句精确的话自然对不上。</span>查询若针对某一节，全篇向量会对上「像这本手册」而不是「超时配置」。需要：要么把检索对象保持在训练长度附近（切分课），要么用层次模型先段后篇，使篇向量由段向量可解释地合成。</p><p>晚切分（先对长文编码再切向量）依赖能处理长上下文的骨干，位置编码与显存是约束。短模型上硬做晚切分没有奇迹。</p><p><span class="marginnote">标题路径拼进块文本（「手册 &gt; 网络 &gt; 超时」）往往比把 \\(d\\) 加倍更能救长文档检索。这是特征，不是新损失。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>默认仍切块，块长落在嵌入训练分布。层次：段向量再过一层浅网络得节/篇向量，查询同时对段与篇检索，命中篇则展开段。滑动窗口重叠规则与切分课一致，避免边界短语失踪。<span class="marginnote">数字实例：嵌入模型训练长度常见 512 token，一份 20 页手册约 1 万 token——直接编码等于扔掉约 95% 的内容还毫不报错，剩下的恰好是文档开头那些最没有信息量的标题页。这是长文档检索「看起来能跑、结果总差点」的常见底因。</span>评测用长文档问答或手册检索，不要用 MTEB 短句 STS 代理。</p>',9)),(e(),r(i,null,{default:a(()=>[B(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20LONG%5B%22%E9%95%BF%E6%96%87%E6%A1%A3%22%5D%20--%3E%20CH%5B%22%E5%88%87%E6%AE%B5%22%5D%0A%20%20CH%20--%3E%20E%5B%22%E6%AE%B5%E5%B5%8C%E5%85%A5%22%5D%0A%20%20E%20--%3E%20H%5B%22%E5%B1%82%E6%AC%A1%E5%90%88%E6%88%90%E8%8A%82%2F%E7%AF%87%22%5D%0A%20%20E%20--%3E%20IX%5B%22%E6%AE%B5%E7%B4%A2%E5%BC%95%22%5D%0A%20%20H%20--%3E%20IX2%5B%22%E7%AF%87%E7%B4%A2%E5%BC%95%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=l("h2",{id:"机制",tabindex:"-1"},[t("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=l("p",null,"对比学习在短正对上训练时，模型从未被迫把「第一节与第九节」放进可加的几何。直接平均是分布外池化。层次合成若也用对比（篇级正对），篇向量才有余弦意义，否则只是段向量的无监督平均。长上下文骨干能看见全篇注意力，但仍只有一个池化出口时，一样会主题化——多向量或切段仍必要。同一个查询走「全篇向量」与「段向量」两条路，命中对象完全不同：",-1)),(e(),r(i,null,{default:a(()=>[B(n,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%3A%20%E8%B6%85%E6%97%B6%E9%85%8D%E7%BD%AE%E6%80%8E%E4%B9%88%E8%AE%BE%22%5D%20--%3E%20FV%5B%22%E5%85%A8%E7%AF%87%E5%90%91%E9%87%8F%22%5D%0A%20%20Q%20--%3E%20SV%5B%22%E6%AE%B5%E5%90%91%E9%87%8F%22%5D%0A%20%20FV%20--%3E%20M1%5B%22%E5%AF%B9%E4%B8%8A%E3%80%8E%E5%83%8F%E8%BF%99%E6%9C%AC%E6%89%8B%E5%86%8C%E3%80%8F%3Cbr%2F%3E%E5%90%8C%E4%B8%BB%E9%A2%98%E6%96%87%E6%A1%A3%E9%83%BD%E6%8E%92%E5%89%8D%E9%9D%A2%22%5D%0A%20%20SV%20--%3E%20M2%5B%22%E5%AF%B9%E4%B8%8A%E3%80%8E%E7%BD%91%E7%BB%9C%20%3E%20%E8%B6%85%E6%97%B6%E3%80%8F%E9%82%A3%E4%B8%80%E6%AE%B5%3Cbr%2F%3E%E7%BB%86%E7%B2%92%E5%BA%A6%E5%91%BD%E4%B8%AD%22%5D%0A%20%20M1%20--%3E%20R1%5B%22%E7%BB%93%E6%9E%9C%3A%20%E6%89%8B%E5%86%8C%E6%89%BE%E5%AF%B9%2C%20%E7%AD%94%E6%A1%88%E6%AE%B5%E6%B2%A1%E6%89%BE%E5%88%B0%22%5D%0A%20%20M2%20--%3E%20R2%5B%22%E7%BB%93%E6%9E%9C%3A%20%E7%9B%B4%E6%8E%A5%E5%91%BD%E4%B8%AD%E7%9B%B8%E5%85%B3%E8%8A%82%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=o('<p><span class="marginnote">常见误区：初学者以为换个 32k 长上下文的嵌入模型就能整篇入库。骨干确实能读完，但只要最后还是压回一个向量出口，池化就把细节抹平了——长输入不是解药，多向量或层次检索才是。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>法律与代码的「长」还带结构（条款、函数）。按 token 切会切断引用。下一课多模态：图文同空间，长度变成视觉 token 数。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>长文单向量易塌成主题；检索对象应对齐训练长度。</li><li>层次合成需要篇级对比，不能只平均段向量。</li><li>用手册级任务评测，不用短句榜代理。</li><li>出处：切分与层次检索工程传统；晚切分依赖长上下文骨干。</li></ul>',5))])}const b=s(p,[["render",m]]);export{C as __pageData,b as default};
